content:
做电路题的时候经常要算欧姆定律、串联并联、分压之类的，写了个小工具方便自己用。

> 直接在下面对应模块输入已知参数，自动算出未知量，还会列出用到的知识点。

<!-- more -->

---

<style>
:root {
  --tool-accent: #7c3aed;
  --tool-accent2: #a78bfa;
  --tool-bg: rgba(255,255,255,0.92);
  --tool-radius: 12px;
  --tool-shadow: 0 2px 12px rgba(0,0,0,0.08);
}
* { box-sizing: border-box; }
.tool-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
@media (max-width: 768px) {
  .tool-grid { grid-template-columns: 1fr; }
}
.tool-card {
  background: var(--tool-bg);
  border: 1px solid #e0d4f0;
  border-radius: var(--tool-radius);
  padding: 20px;
  box-shadow: var(--tool-shadow);
  transition: transform 0.2s;
}
.tool-card:hover { transform: translateY(-2px); }
.tool-card h3 { margin: 0 0 6px; font-size: 16px; color: var(--tool-accent); display:flex; align-items:center; gap:8px; }
.tool-card h3 small { font-size: 12px; font-weight:normal; color:#888; }
.tool-card .formula {
  font-size: 13px; color: #666; margin: 2px 0 12px;
  padding: 4px 8px; background: #f5f0ff; border-radius: 6px; display: inline-block;
}
.input-row {
  display: flex; gap: 8px; margin-bottom: 8px;
  flex-wrap: wrap; align-items: center;
}
.input-row label { font-size: 13px; min-width: 50px; color: #333; }
.input-row input, .input-row select {
  flex: 1; min-width: 60px; padding: 6px 10px;
  border: 1px solid #ddd; border-radius: 6px; font-size: 14px; outline: none;
  transition: border 0.2s;
}
.input-row input:focus, .input-row select:focus {
  border-color: var(--tool-accent);
  box-shadow: 0 0 0 2px rgba(124,58,237,0.15);
}
.input-row input.result {
  background: #f0fdf4; border-color: #86efac; font-weight: bold;
}
.calc-btn {
  background: var(--tool-accent); color: white; border: none;
  padding: 6px 16px; border-radius: 6px; cursor: pointer; font-size: 13px;
  transition: background 0.2s;
}
.calc-btn:hover { background: var(--tool-accent2); }
.clear-btn {
  background: #f3f4f6; color: #555; border: 1px solid #ddd;
  padding: 6px 14px; border-radius: 6px; cursor: pointer; font-size: 12px;
}
.result-area {
  margin-top: 10px; padding: 10px 14px;
  background: #fafafa; border-radius: 8px;
  border-left: 3px solid var(--tool-accent); font-size: 14px; line-height: 1.8;
  display: none;
}
.result-area.show { display: block; }
.result-area .highlight { color: var(--tool-accent); font-weight: bold; }
.knowledge-tag {
  display: inline-block; background: #ede9fe; color: #5b21b6;
  padding: 2px 8px; border-radius: 4px; font-size: 11px; margin: 2px;
}
</style>

<div class="tool-grid">

<!-- 1. 欧姆定律 -->
<div class="tool-card">
  <h3>📐 欧姆定律</h3>
  <div class="formula">V = I × R</div>
  <div class="input-row">
    <label>电压 V</label>
    <input type="number" id="ohm-v" placeholder="V" step="any">
    <select id="ohm-v-unit"><option>V</option><option>mV</option><option>kV</option></select>
  </div>
  <div class="input-row">
    <label>电流 I</label>
    <input type="number" id="ohm-i" placeholder="A" step="any">
    <select id="ohm-i-unit"><option>A</option><option>mA</option><option>µA</option></select>
  </div>
  <div class="input-row">
    <label>电阻 R</label>
    <input type="number" id="ohm-r" placeholder="Ω" step="any">
    <select id="ohm-r-unit"><option>Ω</option><option>kΩ</option><option>MΩ</option></select>
  </div>
  <div style="display:flex;gap:8px">
    <button class="calc-btn" onclick="calcOhm()">计算</button>
    <button class="clear-btn" onclick="clearFields('ohm')">清空</button>
  </div>
  <div id="ohm-result" class="result-area"></div>
</div>

<!-- 2. 串联电路 -->
<div class="tool-card">
  <h3>🔗 串联电路</h3>
  <div class="formula">R总 = R₁ + R₂  I = V / R总</div>
  <div class="input-row">
    <label>R₁</label><input type="number" id="series-r1" placeholder="Ω" step="any">
  </div>
  <div class="input-row">
    <label>R₂</label><input type="number" id="series-r2" placeholder="Ω" step="any">
  </div>
  <div class="input-row">
    <label>电源 V</label><input type="number" id="series-v" placeholder="V" step="any">
  </div>
  <button class="calc-btn" onclick="calcSeries()">计算</button>
  <div id="series-result" class="result-area"></div>
</div>

<!-- 3. 并联电路 -->
<div class="tool-card">
  <h3>🔀 并联电路</h3>
  <div class="formula">1/R总 = 1/R₁ + 1/R₂</div>
  <div class="input-row">
    <label>R₁</label><input type="number" id="para-r1" placeholder="Ω" step="any">
  </div>
  <div class="input-row">
    <label>R₂</label><input type="number" id="para-r2" placeholder="Ω" step="any">
  </div>
  <div class="input-row">
    <label>电源 V</label><input type="number" id="para-v" placeholder="V" step="any">
  </div>
  <button class="calc-btn" onclick="calcParallel()">计算</button>
  <div id="para-result" class="result-area"></div>
</div>

<!-- 4. 分压 -->
<div class="tool-card">
  <h3>🔽 分压电路</h3>
  <div class="formula">Vout = Vin × R₂ / (R₁ + R₂)</div>
  <div class="input-row">
    <label>Vin</label><input type="number" id="div-vin" placeholder="V" step="any">
  </div>
  <div class="input-row">
    <label>R₁</label><input type="number" id="div-r1" placeholder="Ω" step="any">
  </div>
  <div class="input-row">
    <label>R₂</label><input type="number" id="div-r2" placeholder="Ω" step="any">
  </div>
  <button class="calc-btn" onclick="calcDivider()">计算</button>
  <div id="div-result" class="result-area"></div>
</div>

<!-- 5. 功率 -->
<div class="tool-card">
  <h3>🔥 功率计算</h3>
  <div class="formula">P = V×I = I²R = V²/R</div>
  <div class="input-row">
    <label>电压 V</label><input type="number" id="pow-v" placeholder="V" step="any">
  </div>
  <div class="input-row">
    <label>电流 I</label><input type="number" id="pow-i" placeholder="A" step="any">
  </div>
  <div class="input-row">
    <label>电阻 R</label><input type="number" id="pow-r" placeholder="Ω" step="any">
  </div>
  <button class="calc-btn" onclick="calcPower()">计算</button>
  <div id="pow-result" class="result-area"></div>
</div>

<!-- 6. 色环 -->
<div class="tool-card">
  <h3>🎨 电阻色环解码</h3>
  <div class="formula">四环：AB ×10^C ±D%</div>
  <div class="input-row">
    <label>环1</label>
    <select id="cc-1">
      <option value="0">黑 0</option><option value="1">棕 1</option><option value="2">红 2</option>
      <option value="3">橙 3</option><option value="4">黄 4</option><option value="5">绿 5</option>
      <option value="6">蓝 6</option><option value="7">紫 7</option><option value="8">灰 8</option><option value="9">白 9</option>
    </select>
  </div>
  <div class="input-row">
    <label>环2</label>
    <select id="cc-2">
      <option value="0">黑 0</option><option value="1">棕 1</option><option value="2">红 2</option>
      <option value="3">橙 3</option><option value="4">黄 4</option><option value="5">绿 5</option>
      <option value="6">蓝 6</option><option value="7">紫 7</option><option value="8">灰 8</option><option value="9">白 9</option>
    </select>
  </div>
  <div class="input-row">
    <label>倍率</label>
    <select id="cc-3">
      <option value="1">黑 ×1</option><option value="10">棕 ×10</option><option value="100">红 ×100</option>
      <option value="1000">橙 ×1k</option><option value="10000">黄 ×10k</option>
      <option value="100000">绿 ×100k</option><option value="1000000">蓝 ×1M</option>
    </select>
  </div>
  <div class="input-row">
    <label>误差</label>
    <select id="cc-4">
      <option value="±1%">棕 ±1%</option><option value="±2%">红 ±2%</option>
      <option value="±0.5%">绿 ±0.5%</option><option value="±5%">金 ±5%</option><option value="±10%">银 ±10%</option>
    </select>
  </div>
  <button class="calc-btn" onclick="calcColorCode()">解码</button>
  <div id="cc-result" class="result-area"></div>
</div>

<!-- 7. RC -->
<div class="tool-card">
  <h3>⏱️ RC 时间常数</h3>
  <div class="formula">τ = R × C</div>
  <div class="input-row">
    <label>R</label><input type="number" id="rc-r" placeholder="Ω" step="any">
  </div>
  <div class="input-row">
    <label>C</label><input type="number" id="rc-c" placeholder="F" step="any">
  </div>
  <button class="calc-btn" onclick="calcRC()">计算</button>
  <div id="rc-result" class="result-area"></div>
</div>

</div>

<script>
function getUnitValue(id) {
  var v = parseFloat(document.getElementById(id).value);
  if (isNaN(v)) return null;
  var m = { 'V':1, 'mV':0.001, 'kV':1000, 'A':1, 'mA':0.001, 'µA':0.000001, 'Ω':1, 'kΩ':1000, 'MΩ':1000000 };
  var s = document.getElementById(id + '-unit');
  return s ? v * (m[s.value] || 1) : v;
}
function fmt(v) {
  if (v===null||isNaN(v)) return '—';
  if (Math.abs(v)>=1e6) return (v/1e6).toFixed(3)+'M';
  if (Math.abs(v)>=1e3) return (v/1e3).toFixed(3)+'k';
  if (Math.abs(v)>=1) return v.toFixed(3);
  if (Math.abs(v)>=1e-3) return (v*1e3).toFixed(3)+'m';
  return v.toExponential(3);
}
function fmtR(v) {
  if (v>=1e6) return (v/1e6).toFixed(2)+' MΩ';
  if (v>=1e3) return (v/1e3).toFixed(2)+' kΩ';
  return v.toFixed(2)+' Ω';
}
function showRes(id, html, tags) {
  var el = document.getElementById(id);
  el.innerHTML = html + (tags ? '<br>📖 '+tags.map(function(t){return '<span class=knowledge-tag>'+t+'</span>'}).join('') : '');
  el.classList.add('show');
}
function clearFields(p) {
  document.querySelectorAll('[id^="'+p+'-"]').forEach(function(e){if(e.tagName==='INPUT')e.value=''});
  var r = document.getElementById(p+'-result'); if(r) r.classList.remove('show');
}
function calcOhm() {
  var v=getUnitValue('ohm-v'), i=getUnitValue('ohm-i'), r=getUnitValue('ohm-r');
  var n=[v!==null,i!==null,r!==null].filter(Boolean).length;
  if(n<2){showRes('ohm-result','⚠️ 至少输入两个');return;}
  var h='',k=['欧姆定律 V=IR'];
  if(v===null){v=i*r;h+='V = '+fmt(i)+'×'+fmt(r)+' = <span class=highlight>'+fmt(v)+' V</span><br>';}
  if(i===null){i=v/r;h+='I = '+fmt(v)+'/'+fmt(r)+' = <span class=highlight>'+fmt(i)+' A</span><br>';}
  if(r===null){r=v/i;h+='R = '+fmt(v)+'/'+fmt(i)+' = <span class=highlight>'+fmtR(r)+'</span><br>';}
  showRes('ohm-result',h,k);
}
function calcSeries() {
  var r1=parseFloat(document.getElementById('series-r1').value);
  var r2=parseFloat(document.getElementById('series-r2').value);
  var v=parseFloat(document.getElementById('series-v').value);
  if(isNaN(r1)||isNaN(r2)||isNaN(v)){showRes('series-result','⚠️ 请填全');return;}
  var rt=r1+r2, i=v/rt, v1=i*r1, v2=i*r2;
  showRes('series-result','R总='+fmtR(rt)+'<br>I='+fmt(i)+' A<br>V₁='+fmt(v1)+' V<br>V₂='+fmt(v2)+' V',['串联R总=R₁+R₂','分压原理']);
}
function calcParallel() {
  var r1=parseFloat(document.getElementById('para-r1').value);
  var r2=parseFloat(document.getElementById('para-r2').value);
  var v=parseFloat(document.getElementById('para-v').value);
  if(isNaN(r1)||isNaN(r2)||isNaN(v)){showRes('para-result','⚠️ 请填全');return;}
  var rt=1/(1/r1+1/r2), i1=v/r1, i2=v/r2, it=i1+i2;
  showRes('para-result','R总='+fmtR(rt)+'<br>I₁='+fmt(i1)+' A<br>I₂='+fmt(i2)+' A<br>I总='+fmt(it)+' A',['并联1/R总=1/R₁+1/R₂','KCL']);
}
function calcDivider() {
  var vin=parseFloat(document.getElementById('div-vin').value);
  var r1=parseFloat(document.getElementById('div-r1').value);
  var r2=parseFloat(document.getElementById('div-r2').value);
  if(isNaN(vin)||isNaN(r1)||isNaN(r2)){showRes('div-result','⚠️ 请填全');return;}
  var vout=vin*r2/(r1+r2);
  showRes('div-result','Vout='+fmt(vin)+'×'+fmtR(r2)+'/'+fmtR(r1+r2)+'<br>=<span class=highlight>'+fmt(vout)+' V</span><br>分压比='+(r2/(r1+r2)*100).toFixed(1)+'%',['分压公式']);
}
function calcPower() {
  var v=parseFloat(document.getElementById('pow-v').value);
  var i=parseFloat(document.getElementById('pow-i').value);
  var r=parseFloat(document.getElementById('pow-r').value);
  var n=[!isNaN(v),!isNaN(i),!isNaN(r)].filter(Boolean).length;
  if(n<2){showRes('pow-result','⚠️ 至少输入两个');return;}
  var h='',k=['P=VI=I²R=V²/R'];
  if(!isNaN(v)&&!isNaN(i)){h='P='+fmt(v)+'×'+fmt(i)+'=<span class=highlight>'+fmt(v*i)+' W</span><br>';if(isNaN(r)){r=v/i;h+='R='+fmtR(r)+'<br>';k.push('欧姆定律');}}
  if(!isNaN(i)&&!isNaN(r)&&isNaN(v)){v=i*r;h+='V='+fmt(v)+' V<br>P=I²R='+fmt(i*i*r)+' W<br>';k.push('欧姆定律');}
  if(!isNaN(v)&&!isNaN(r)&&isNaN(i)){i=v/r;h+='I='+fmt(i)+' A<br>P=V²/R='+fmt(v*v/r)+' W<br>';k.push('欧姆定律');}
  showRes('pow-result',h,k);
}
function calcColorCode() {
  var d1=parseInt(document.getElementById('cc-1').value);
  var d2=parseInt(document.getElementById('cc-2').value);
  var mul=parseFloat(document.getElementById('cc-3').value);
  var err=document.getElementById('cc-4').value;
  var val=(d1*10+d2)*mul;
  showRes('cc-result','阻值=<span class=highlight>'+fmtR(val)+'</span><br>误差='+err,['色环读数']);
}
function calcRC() {
  var r=parseFloat(document.getElementById('rc-r').value);
  var c=parseFloat(document.getElementById('rc-c').value);
  if(isNaN(r)||isNaN(c)){showRes('rc-result','⚠️ 请填全');return;}
  var tau=r*c;
  showRes('rc-result','τ=R×C='+fmtR(r)+'×'+fmt(c)+'F<br>=<span class=highlight>'+fmt(tau)+' 秒</span><br>5τ≈'+fmt(tau*5)+' s 充满',['RC时间常数τ=RC']);
}
</script>
